def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Filter out statements about the day of the week
    filtered_statements = {participant: [stmt for stmt in stmts if not stmt.startswith("Today is")] for participant, stmts in statements.items()}

    # Check each participant's statements
    for participant, stmts in filtered_statements.items():
        # Determine if the participant is a liar or not
        is_liar = participant in liar_count

        # Check each statement
        for stmt in stmts:
            if participant == scenario:
                # If the participant is the scenario, their statements should be consistent with being the criminal
                if is_liar and "I am guilty." in stmts:
                    return False
                if not is_liar and "I am not guilty." in stmts:
                    return False
            else:
                # If the participant is not the scenario, their statements should be consistent with the scenario
                if is_liar and stmt == f"{scenario} is guilty.":
                    return False
                if not is_liar and stmt == f"{scenario} is not guilty.":
                    return False

    # If all statements are consistent, return True
    return True
